# ----------------------------------------------------------------------
# CUDA source for fp16 Sigmoid (forward & backward)
# ----------------------------------------------------------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

template <typename scalar_t>
__global__ void sigmoid_forward_kernel(const scalar_t* __restrict__ input,
                                       scalar_t* __restrict__ output,
                                       size_t N) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N) return;

    // Convert half to float for computation
    float x = static_cast<float>(input[idx]);
    float y = 1.0f / (1.0f + expf(-x));
    output[idx] = static_cast<scalar_t>(y);
}

template <typename scalar_t>
__global__ void sigmoid_backward_kernel(const scalar_t* __restrict__ grad_output,
                                        const scalar_t* __restrict__ output,
                                        scalar_t* __restrict__ grad_input,
                                        size_t N) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N) return;

    float y = static_cast<float>(output[idx]);          // sigmoid(x)
    float go = static_cast<float>(grad_output[idx]);   // upstream grad
    float gi = go * y * (1.0f - y);                     // dy/dx * go
    grad_input[idx] = static_cast<scalar_t>(gi);
}

// Dispatcher for forward
void sigmoid_forward(at::Tensor input, at::Tensor output) {
    const size_t N = input.numel();
    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "sigmoid_forward_kernel", ([&] {
        sigmoid_forward_kernel<scalar_t><<<blocks, threads, 0,
            at::cuda::getCurrentCUDAStream()>>>(
                input.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                N);
    }));
}

// Dispatcher for backward
void sigmoid_backward(at::Tensor grad_output,
                      at::Tensor output,
                      at::Tensor grad_input) {
    const size_t N = grad_output.numel();
    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(grad_output.scalar_type(), "sigmoid_backward_kernel", ([&] {
        sigmoid_backward_kernel<scalar_t><<<blocks, threads, 0,
            at::cuda::getCurrentCUDAStream()>>>(
                grad_output.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                grad_input.data_ptr<scalar_t>(),
                N);
    }));
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &sigmoid_forward, "Sigmoid forward (fp16)");
    m.def("backward", &sigmoid_backward, "Sigmoid backward (fp16)");
}
'''

# ----------------------------------------------------------------------
# Compile the extension
# ----------------------------------------------------------------------
sigmoid_ext = load_inline(name='sigmoid_ext',
                          cpp_sources='',
                          cuda_sources=src,
                          functions=['forward', 'backward'],
                          verbose=False)

# ----------------------------------------------------------------------
# Autograd Function using the compiled kernels
# ----------------------------------------------------------------------
class SigmoidFunction(Function):
    @staticmethod
    def forward(ctx, input):
        if not input.is_cuda:
            raise RuntimeError("SigmoidFunction only supports CUDA tensors")
        if input.dtype != torch.float16:
            raise RuntimeError("SigmoidFunction expects float16 tensors")
        output = torch.empty_like(input)
        sigmoid_ext.forward(input, output)
        ctx.save_for_backward(output)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        output, = ctx.saved_tensors
        grad_input = torch.empty_like(grad_output)
        sigmoid_ext.backward(grad_output, output, grad_input)
        return grad_input

# ----------------------------------------------------------------------
# ModelNew definition (drop‑in replacement for the reference Model)
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Model that applies a custom CUDA fp16 Sigmoid.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return SigmoidFunction.apply(x)

# ----------------------------------------------------------------------
# Helper functions matching the reference API
# ----------------------------------------------------------------------
def get_inputs():
    # Using the same dimensions as the reference
    batch_size = 4096
    dim = 393216
    x = torch.rand(batch_size, dim, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return []  # No special initialization needed
